import{_ as e,o as a,c as o,a5 as c}from"./chunks/framework.Bqo7-qSd.js";const u=JSON.parse('{"title":"选项","description":"","frontmatter":{"title":"选项","order":7},"headers":[],"relativePath":"zh/latest/tutorial/script/choice.md","filePath":"zh/latest/tutorial/script/choice.md","lastUpdated":1795484315000}'),s={name:"zh/latest/tutorial/script/choice.md"};function d(i,t,n,l,r,p){return a(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="选项跳转" tabindex="-1">选项跳转 <a class="header-anchor" href="#选项跳转" aria-label="Permalink to &quot;选项跳转&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>该功能需与<strong>分支功能</strong>搭配使用，核心作用是在交互选项标签中配置跳转逻辑。点击对应选项后可直接跳转到指定分支。每个 <code>choice</code> 语句创建一个选项，多个相邻的 <code>choice</code> 行会被合并为一个选项组，同时展示。</p><p>选项可选地带一个<strong>可见条件</strong>（<code>if</code>）和<strong>一次性标记</strong>（<code>once</code>），用来表达“好感度足够才出现”“问过一次就不再出现”这类常见需求。</p><h2 id="语法规范" tabindex="-1">语法规范 <a class="header-anchor" href="#语法规范" aria-label="Permalink to &quot;语法规范&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;选项内容&quot; -&gt; 分支名称 [if %变量 运算符 值] [once]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>必填</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>选项内容</td><td>是</td><td><code>&quot;选择咖啡&quot;</code></td><td>交互时展示的选项文本</td></tr><tr><td>分支名称</td><td>是</td><td><code>coffee_choice</code></td><td>需跳转的目标分支唯一标识</td></tr><tr><td><code>if</code> 条件</td><td>否</td><td><code>if %love &gt;= 5</code></td><td>条件成立时才显示该选项</td></tr><tr><td><code>once</code></td><td>否</td><td><code>once</code></td><td>选中一次后不再出现</td></tr></tbody></table><p><code>if</code> 与 <code>once</code> 的顺序任意，但各自最多出现一次。条件支持与 <code>if</code> 语句相同的六种比较运算符，右值可以是数字、字符串、布尔值或变量。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><p>每个选项单独一行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea</span></span>
<span class="line"><span>choice &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><p>带条件与一次性选项：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;送花（好感+10）&quot; -&gt; gift_flower</span></span>
<span class="line"><span>choice &quot;送书（好感+5）&quot; -&gt; gift_book if %love &gt;= 5</span></span>
<span class="line"><span>choice &quot;（已问过）镇上的传闻&quot; -&gt; rumor</span></span>
<span class="line"><span>choice &quot;（只问一次）神秘商人&quot; -&gt; merchant once</span></span>
<span class="line"><span>choice &quot;什么都不送&quot; -&gt; gift_none</span></span></code></pre></div><h2 id="行为说明" tabindex="-1">行为说明 <a class="header-anchor" href="#行为说明" aria-label="Permalink to &quot;行为说明&quot;">​</a></h2><ul><li><strong>条件不成立</strong>：选项被隐藏；如果整个选项组没有任何可用项，会<strong>直接继续执行选择组之后的语句</strong>，不会显示空菜单。</li><li><strong>条件变量不存在或类型不兼容</strong>：按“条件不成立”处理，并只在控制台警告一次，不会打断剧情。</li><li><strong><code>once</code> 的身份</strong>：由“choice 指令稳定键 + 目标分支稳定键 + 组内序号”组成，因此切换语言或修改选项文案不会让“已选过”失效；重排选项会被视为新的选项。</li><li><strong>回退与存档</strong>：<code>once</code> 的使用记录属于运行期状态，会随“上一句”回退、检查点和存档一起还原；<code>init_dialogue()</code> 开始新游戏时会清空。</li><li><strong>命名参数</strong>：选项组的命名参数（例如 <code>[id=...]</code>）只能写在第一项。</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li>分支名称需与剧本中定义的分支标识完全一致，区分大小写，不可包含空格或特殊符号。</li><li>选项内容需用英文双引号包裹。</li><li><code>-&gt;</code> 是选项与分支名称之间的分隔符，不可省略。</li><li><code>once</code> 记录的是“这个菜单项”，不是“这个分支”；不同菜单里指向同一分支的选项互不影响。</li></ol>`,17)])])}const g=e(s,[["render",d]]);export{u as __pageData,g as default};
